import 'dart:async';
import 'dart:math' as math;
import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'models.dart';
import 'usb_serial_service.dart';

const bg = Color(0xff0c141c), glass = Color(0xcc0c141c), blue = Color(0xff4ca6ff), green = Color(0xff45c486), amber = Color(0xffe9c176), red = Color(0xffe74c3c), textDim = Color(0xff9aa8b2);
const panelTitle = TextStyle(color: textDim, fontSize: 10, fontWeight: FontWeight.bold, letterSpacing: 1.1);

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  await SystemChrome.setPreferredOrientations(const [
    DeviceOrientation.landscapeLeft,
    DeviceOrientation.landscapeRight,
  ]);
  runApp(const CockpitApp());
}
class CockpitApp extends StatelessWidget { const CockpitApp({super.key}); @override Widget build(BuildContext context) => MaterialApp(debugShowCheckedModeBanner: false, title: 'Control de luces', theme: ThemeData.dark(useMaterial3: true).copyWith(scaffoldBackgroundColor: bg, colorScheme: const ColorScheme.dark(primary: blue, surface: bg)), home: const CockpitScreen()); }
class CockpitScreen extends StatefulWidget { const CockpitScreen({super.key}); @override State<CockpitScreen> createState() => _CockpitState(); }
class _CockpitState extends State<CockpitScreen> {
  final service = AndroidUsbSerialService(); VehicleState state = const VehicleState(); UsbConnectionState connection = UsbConnectionState.disconnected; StreamSubscription? stateSubscription, connectionSubscription; Timer? blinkTimer; bool demo = true; String message = 'SIN DISPOSITIVO';
  @override void initState() { super.initState(); stateSubscription = service.vehicleState.listen((value) { if (mounted) setState(() => state = value); }); connectionSubscription = service.connectionState.listen((value) { if (mounted) setState(() { connection = value; message = _status(value); if (value == UsbConnectionState.connected) demo = false; if (value == UsbConnectionState.disconnected) { demo = true; state = const VehicleState(); } }); }); blinkTimer = Timer.periodic(const Duration(milliseconds: 500), (_) { if (mounted && (state.leftTurn || state.rightTurn || state.hazard)) setState(() => state = state.copyWith(blinkOn: !state.blinkOn)); }); }
  String _status(UsbConnectionState value) => switch (value) { UsbConnectionState.connected => 'CONECTADO', UsbConnectionState.waitingPermission => 'ESPERANDO PERMISO', UsbConnectionState.connecting => 'CONECTANDO', UsbConnectionState.error => 'ERROR DE COMUNICACIÓN', _ => 'DESCONECTADO' };
  Future<void> _connect() async { try { final devices = await service.discoverDevices(); if (devices.isEmpty) { setState(() => message = 'NO SE ENCONTRÓ USB'); return; } await service.connect(devices.first); setState(() => demo = false); } catch (_) { setState(() { connection = UsbConnectionState.error; message = 'ERROR USB'; }); } }
  void _change(VehicleState next) {
    if (demo) {
      setState(() => state = next.copyWith(isConfirmed: false));
    } else if (connection == UsbConnectionState.connected) {
      service.sendCommand(next);
    }
  }
  void _toggle(String key) { final current = state; _change(current.copyWith(lowBeam: key == 'low' ? !current.lowBeam : key == 'high' ? false : current.lowBeam, highBeam: key == 'high' ? !current.highBeam : key == 'low' ? false : current.highBeam, leftTurn: key == 'left' ? !current.leftTurn : (key == 'right' || key == 'hazard') ? false : current.leftTurn, rightTurn: key == 'right' ? !current.rightTurn : (key == 'left' || key == 'hazard') ? false : current.rightTurn, hazard: key == 'hazard' ? !current.hazard : (key == 'left' || key == 'right') ? false : current.hazard)); }
  @override void dispose() { stateSubscription?.cancel(); connectionSubscription?.cancel(); blinkTimer?.cancel(); service.dispose(); super.dispose(); }

  @override Widget build(BuildContext context) => Scaffold(body: Stack(fit: StackFit.expand, children: [Image.asset('design/stitch_autodrive_cockpit_ui_ux_simulator/peugeot-408-interior.jpg', fit: BoxFit.cover), const DecoratedBox(decoration: BoxDecoration(gradient: LinearGradient(begin: Alignment.topCenter, end: Alignment.bottomCenter, colors: [Color(0xb3000000), Color(0x22000000), Color(0xd9000000)]))), SafeArea(child: LayoutBuilder(builder: (_, constraints) => Padding(padding: const EdgeInsets.all(12), child: Column(children: [_topBar(), const Spacer(), _bottomBar(constraints.maxWidth)]))))]));
  Widget _topBar() => Row(crossAxisAlignment: CrossAxisAlignment.start, children: [Expanded(child: _connectionPanel()), const SizedBox(width: 10), Expanded(flex: 2, child: _indicatorPanel()), const SizedBox(width: 10), Expanded(child: _hardwarePanel())]);
  Widget _connectionPanel() => _glass(Row(children: [Container(width: 8, height: 8, decoration: BoxDecoration(color: connection == UsbConnectionState.connected ? green : amber, shape: BoxShape.circle)), const SizedBox(width: 8), Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [const Text('ARDUINO', style: panelTitle), Text('$message • USB OTG', style: const TextStyle(color: green, fontSize: 10, fontWeight: FontWeight.bold)), if (demo) const Text('MODO DEMOSTRACIÓN', style: TextStyle(color: textDim, fontSize: 8))])), IconButton(visualDensity: VisualDensity.compact, onPressed: demo ? _connect : service.disconnect, icon: Icon(demo ? Icons.link : Icons.link_off, color: blue, size: 18))]));
  Widget _indicatorPanel() => _glass(Row(mainAxisAlignment: MainAxisAlignment.spaceEvenly, children: [_indicator(Icons.turn_left, 'IZQ', (state.hazard || state.leftTurn) && state.blinkOn, state.hazard ? amber : green), _indicator(Icons.flare, 'LUZ ALTA', state.highBeam, blue), _indicator(Icons.lightbulb_outline, 'LUZ BAJA', state.lowBeam, green), _indicator(Icons.do_not_disturb_on, 'FRENO', state.brake, red), _indicator(Icons.turn_right, 'DER', (state.hazard || state.rightTurn) && state.blinkOn, state.hazard ? amber : green)]));
  Widget _hardwarePanel() => _glass(const Column(crossAxisAlignment: CrossAxisAlignment.end, children: [Text('MEGA 2560', style: panelTitle), Text('CH340 • 115200 BAUD', style: TextStyle(color: blue, fontSize: 10, fontWeight: FontWeight.bold)), Text('BUS SERIAL LOCAL', style: TextStyle(color: textDim, fontSize: 8))]));
  Widget _bottomBar(double width) => SizedBox(height: math.min(166, width * .24), child: Row(crossAxisAlignment: CrossAxisAlignment.stretch, children: [Expanded(flex: 4, child: _lightingPanel()), const SizedBox(width: 10), Expanded(flex: 2, child: _hazardPanel()), const SizedBox(width: 10), Expanded(flex: 3, child: _brakePanel())]));
  Widget _lightingPanel() => _glass(Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [const Text('CONTROLES DE ILUMINACIÓN', style: panelTitle), const SizedBox(height: 8), Expanded(child: GridView.count(physics: const NeverScrollableScrollPhysics(), crossAxisCount: 2, crossAxisSpacing: 6, mainAxisSpacing: 6, childAspectRatio: 5, children: [ _switchButton('LUZ ALTA', Icons.flare, state.highBeam, blue, () => _toggle('high')), _switchButton('LUZ BAJA', Icons.lightbulb_outline, state.lowBeam, green, () => _toggle('low')), _switchButton('GIRO IZQUIERDA', Icons.arrow_back, state.leftTurn, green, () => _toggle('left')), _switchButton('GIRO DERECHA', Icons.arrow_forward, state.rightTurn, green, () => _toggle('right'))]))]));
  Widget _hazardPanel() => _glass(Column(mainAxisAlignment: MainAxisAlignment.center, children: [const Text('PRECAUCIÓN', style: panelTitle), const SizedBox(height: 6), Expanded(child: Center(child: AspectRatio(aspectRatio: 1.2, child: Material(color: state.hazard ? red : red.withValues(alpha: .16), shape: const RoundedRectangleBorder(borderRadius: BorderRadius.all(Radius.circular(10))), child: InkWell(onTap: () => _toggle('hazard'), borderRadius: const BorderRadius.all(Radius.circular(10)), child: Container(decoration: BoxDecoration(border: Border.all(color: red, width: 2), borderRadius: const BorderRadius.all(Radius.circular(10)), boxShadow: state.hazard ? [const BoxShadow(color: red, blurRadius: 18)] : null), child: const Center(child: Icon(Icons.warning_amber_rounded, color: Colors.white, size: 38)))))))), Text(state.hazard ? 'BALIZAS ACTIVAS' : 'BALIZAS', style: TextStyle(color: state.hazard ? Colors.white : red, fontSize: 10, fontWeight: FontWeight.bold))]));
  Widget _brakePanel() => _glass(Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [const Text('PEDAL DE FRENO', style: panelTitle), const Spacer(), GestureDetector(onTap: () => _change(state.copyWith(brake: !state.brake)), child: Container(height: 74, decoration: BoxDecoration(color: Colors.black.withValues(alpha: .42), border: Border.all(color: state.brake ? red : textDim.withValues(alpha: .5), width: state.brake ? 2 : 1), borderRadius: const BorderRadius.all(Radius.circular(8)), boxShadow: state.brake ? [const BoxShadow(color: red, blurRadius: 9, spreadRadius: 1)] : null), child: Center(child: Column(mainAxisAlignment: MainAxisAlignment.center, children: [Icon(Icons.do_not_disturb_on, color: state.brake ? red : textDim, size: 24), Text(state.brake ? 'FRENO ACTIVO' : 'PISAR FRENO', style: TextStyle(color: state.brake ? Colors.white : Colors.white70, fontSize: 11, fontWeight: FontWeight.bold, letterSpacing: .6))])))), const Spacer(), Text(demo ? 'SIMULACIÓN LOCAL' : 'SALIDA D27', style: const TextStyle(color: textDim, fontSize: 8))]));
  Widget _switchButton(String label, IconData icon, bool active, Color color, VoidCallback onTap) => Material(color: active ? color.withValues(alpha: .22) : Colors.black.withValues(alpha: .28), child: InkWell(onTap: onTap, child: Container(padding: const EdgeInsets.symmetric(horizontal: 7), decoration: BoxDecoration(border: Border.all(color: active ? color : blue.withValues(alpha: .35)), boxShadow: active ? [BoxShadow(color: color.withValues(alpha: .45), blurRadius: 8)] : null), child: Row(children: [Icon(icon, color: active ? color : textDim, size: 18), const SizedBox(width: 5), Expanded(child: Text(label, overflow: TextOverflow.ellipsis, style: TextStyle(color: active ? color : Colors.white70, fontSize: 9, fontWeight: FontWeight.bold)))]))));
  Widget _indicator(IconData icon, String label, bool active, Color color) => Column(mainAxisSize: MainAxisSize.min, children: [Icon(icon, color: active ? color : textDim.withValues(alpha: .35), size: 20), Text(label, style: TextStyle(color: active ? color : textDim.withValues(alpha: .55), fontSize: 8, fontWeight: FontWeight.bold))]);
  Widget _glass(Widget child) => Container(padding: const EdgeInsets.all(10), decoration: BoxDecoration(color: glass, border: Border.all(color: blue.withValues(alpha: .3)), borderRadius: const BorderRadius.all(Radius.circular(12)), boxShadow: [BoxShadow(color: Colors.black.withValues(alpha: .3), blurRadius: 12)]), child: child);
}
